parts.openscad_module:
$fn = 96;

shaft_a        = 5;
shaft_b        = 8;
bore_clearance = 0.2;
outer_d        = 20;
coupler_l      = 30;
clamp_gap      = 1.2;
screw_d        = 3.2;

module rigid_clamp_coupler() {
  difference() {
    cylinder(h = coupler_l, d = outer_d, center = true);
    translate([0, 0,  coupler_l/4])
      cylinder(h = coupler_l/2 + 1, d = shaft_a + bore_clearance, center = true, $fn = 64);
    translate([0, 0, -coupler_l/4])
      cylinder(h = coupler_l/2 + 1, d = shaft_b + bore_clearance, center = true, $fn = 64);
    cube([outer_d + 2, clamp_gap, coupler_l * 0.6], center = true);
    for (z = [coupler_l/4, -coupler_l/4])
      translate([0, 0, z])
        rotate([90, 0, 0])
          cylinder(h = outer_d + 2, d = screw_d, center = true, $fn = 32);
  }
}

rigid_clamp_coupler();
